"""Draw the example game's transition mask (F09 build step 5, PR-F09-26) into
``game/masks/``, with its license record:

    .venv/Scripts/python tests/fixtures/F09/make_example_mask.py            # game/
    .venv/Scripts/python tests/fixtures/F09/make_example_mask.py <folder>   # another game

``masks/lantern_glow.png`` is 640×360 and gray (red = green = blue in every pixel), so the
engine reads its values exactly (``docs/script-language.md``, "Transitions and effects").
It is a paper lantern's glow: an upright oval, darkest in the middle (where ``Mask``
reveals the new picture first) and lightest in the corners (last), with faint horizontal
ribs like a lantern's paper. Nothing is random, so the file is the same every time.
``tests/test_docs.py`` (AC-F09-44) checks its size, its grayness, and its license entry.
"""

import hashlib
import math
import sys
from pathlib import Path

import pygame

GAME = Path(__file__).resolve().parents[3] / "game"
SIZE = (640, 360)                        # the largest size the engine reads exactly
CENTER = (320.0, 186.0)
RADII = (190.0, 230.0)                   # an upright oval, like a paper lantern
RIB_PERIOD = 30.0                        # pixels between ribs
RIB_DEPTH = 0.02                         # how much the ribs bend the edge
MASK = "masks/lantern_glow.png"
LICENSE_RECORD = "masks/LICENSES.txt"


def lantern_glow() -> bytes:
    """The mask's gray values, row by row (one byte per pixel)."""
    width, height = SIZE
    cx, cy = CENTER
    rx, ry = RADII
    raw = []
    for y in range(height):
        rib = 1.0 + RIB_DEPTH * math.cos(2.0 * math.pi * (y - cy) / RIB_PERIOD)
        dy = (y + 0.5 - cy) / ry
        for x in range(width):
            dx = (x + 0.5 - cx) / rx
            raw.append(math.hypot(dx, dy) * rib)
    low, high = min(raw), max(raw)
    return bytes(round(255 * (d - low) / (high - low)) for d in raw)


def mask_surface() -> pygame.Surface:
    gray = lantern_glow()
    rgb = bytes(v for g in gray for v in (g, g, g))
    return pygame.image.frombuffer(rgb, SIZE, "RGB").copy()


def license_record(data: bytes) -> str:
    """``masks/LICENSES.txt``, in the form of ``audio/LICENSES.txt``."""
    return "\n".join([
        "License records for the example game's transition masks (PR-F09-26).",
        "",
        "Every file in this folder is original: generated by",
        "tests/fixtures/F09/make_example_mask.py in the vn-engine repository (pygame, no",
        "randomness), by the vn-engine contributors, and dedicated to the public domain under",
        "CC0 1.0 (https://creativecommons.org/publicdomain/zero/1.0/). Use them in your own",
        "game with no credit needed. To make them again:",
        "",
        "    .venv/Scripts/python tests/fixtures/F09/make_example_mask.py",
        "",
        "When you add a mask of your own, add an entry for it here: who made it, where it",
        "came from, and its license.",
        "",
        f"File: {MASK.removeprefix('masks/')}",
        "License: CC0 1.0 (original)",
        "Author: vn-engine contributors",
        "Source: lantern_glow(), tests/fixtures/F09/make_example_mask.py",
        f"SHA-256: {hashlib.sha256(data).hexdigest()}",
    ]) + "\n"


def write_mask(game: Path) -> list[Path]:
    """Write the mask and its license record under ``game`` (LF line ends)."""
    path = game / MASK
    path.parent.mkdir(parents=True, exist_ok=True)
    pygame.image.save(mask_surface(), str(path))
    record = game / LICENSE_RECORD
    record.write_bytes(license_record(path.read_bytes()).encode("utf-8"))
    return [path, record]


if __name__ == "__main__":
    if len(sys.argv) > 2:
        sys.exit("usage: make_example_mask.py [game folder]")
    root = Path(sys.argv[1]) if len(sys.argv) == 2 else GAME
    for written in write_mask(root):
        print(f"{written.stat().st_size:>8,}  {written}")
